const content = $json.content;

// ابحث عن الجزء الذي نوعه text داخل رد Claude
const textItem = Array.isArray(content)
  ? content.find(item => item.type === "text")
  : null;

if (!textItem || !textItem.text) {
  return [
    {
      json: {
        error: "No response received from Claude"
      }
    }
  ];
}

// تنظيف الرد في حال Claude أضاف ```json
const rawText = textItem.text
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

try {
  const parsed = JSON.parse(rawText);

  return [
    {
      json: parsed
    }
  ];
} catch (error) {
  return [
    {
      json: {
        error: "Invalid JSON returned from Claude",
        raw: rawText
      }
    }
  ];
}

